import java.io.InputStream;
import java.io.OutputStream;
import java.nio.file.Files;
import java.nio.file.Path;

class CopyWithByteStreams {
    public static void main(String[] args) throws Exception {
        Path source = Files.write(Files.createTempFile("source-", ".bin"), new byte[] {1, 2, 3});
        Path target = Files.createTempFile("target-", ".bin");
        try {
            long copied;
            try (InputStream in = Files.newInputStream(source);
                 OutputStream out = Files.newOutputStream(target)) {
                copied = in.transferTo(out);
            }
            System.out.println(copied + " bytes: " + Files.size(target));
        } finally {
            Files.deleteIfExists(source);
            Files.deleteIfExists(target);
        }
    }
}
